import { Diagnostic } from '@codemirror/lint';
import { useCallback, useRef } from 'react';

import { DQLEditorValidityInfo } from './DQLEditor.js';

/**
 * @internal
 */
export const useValidityInfo = (
  onValidityChange?: (validityInfo: DQLEditorValidityInfo[]) => void,
) => {
  const currentDiagnosticsRef = useRef<Diagnostic[]>([]);
  const onValidityChangeRef = useRef<typeof onValidityChange>();

  onValidityChangeRef.current = onValidityChange;

  const setDqlValidityInfo = useCallback(
    (diagnostics: Diagnostic[]) => {
      if (
        onValidityChangeRef.current &&
        JSON.stringify(diagnostics) !==
          JSON.stringify(currentDiagnosticsRef.current)
      ) {
        currentDiagnosticsRef.current = diagnostics;
        const validityInfo: DQLEditorValidityInfo[] = diagnostics.map(
          (diagnostic: Diagnostic): DQLEditorValidityInfo => {
            return {
              ...diagnostic,
              severity:
                diagnostic.severity === 'hint' ? 'info' : diagnostic.severity,
            };
          },
        );

        onValidityChangeRef.current(validityInfo);
      }
    },
    // Avoid adding any dependencies to prevent reconfiguring the editor when currentDiagnostics changes
    [],
  );

  return setDqlValidityInfo;
};
